import "./list.css";

export interface ListProps {
  items: { text: string }[];
  style: "bullet" | "numbered" | "check";
}

export function List({ items, style }: ListProps) {
  const Tag = style === "numbered" ? "ol" : "ul";
  return (
    <div className="p1-list p1-block" data-style={style}>
      <Tag className="p1-list__items">
        {items.map((item, i) => (
          <li key={i} className="p1-list__item">
            <span className="p1-list__marker" aria-hidden="true" />
            <span className="p1-list__text">{item.text}</span>
          </li>
        ))}
      </Tag>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { List, type ListProps } from "./list";
export type { ListProps };

export const ListBlock: ComponentConfig<ListProps> = {
  fields: {
    items: {
      type: "array",
      arrayFields: {
        text: {
          type: "text" as const,
          ai: {
            instructions:
              "A single concise list item. Plain text, sentence case, no trailing punctuation except for complete sentences.",
          },
        },
      },
      defaultItemProps: {
        text: "A clear, scannable list item",
      },
    },
    style: {
      type: "radio" as const,
      options: [
        { label: "Bullet", value: "bullet" },
        { label: "Numbered", value: "numbered" },
        { label: "Check", value: "check" },
      ],
    },
  },
  defaultProps: {
    items: [
      { text: "First item that gets the reader's attention" },
      { text: "Second item with supporting detail" },
      { text: "Third item that rounds out the set" },
    ],
    style: "bullet",
  },
  render: List,
};

export const meta = defineMeta({
  title: 'List',
  description: 'Bullet, numbered, or checkmark list of text items; use for simple inline content lists.',
  categories: ["content"],
  published: true,
});

.p1-list__items {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: var(--p1-space-sm);
  max-inline-size: 65ch;
}

.p1-list__item {
  display: flex;
  align-items: baseline;
  gap: var(--p1-space-sm);
  font-size: var(--p1-text-base);
  color: var(--p1-fg-muted);
  line-height: var(--p1-leading-normal);
}

.p1-list__text {
  flex: 1;
}

/* Bullet marker */
.p1-list[data-style="bullet"] .p1-list__marker {
  flex-shrink: 0;
  inline-size: 0.375rem;
  block-size: 0.375rem;
  border-radius: var(--p1-radius-pill);
  background: var(--p1-accent);
  margin-block-start: 0.45em;
}

/* Numbered marker — CSS counter */
.p1-list[data-style="numbered"] .p1-list__items {
  counter-reset: list-counter;
}

.p1-list[data-style="numbered"] .p1-list__item {
  counter-increment: list-counter;
}

.p1-list[data-style="numbered"] .p1-list__marker {
  flex-shrink: 0;
  min-inline-size: 1.25rem;
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  color: var(--p1-accent);
  line-height: 1;
}

.p1-list[data-style="numbered"] .p1-list__marker::before {
  content: counter(list-counter) ".";
}

/* Check marker */
.p1-list[data-style="check"] .p1-list__marker {
  flex-shrink: 0;
  inline-size: 1rem;
  block-size: 1rem;
  background: var(--p1-accent);
  border-radius: 2px;
  clip-path: polygon(14% 44%, 0 65%, 50% 100%, 100% 16%, 80% 0%, 43% 62%);
  margin-block-start: 0.15em;
}

